// Package context — BindInput 提供 Schema-first 路由的標準化請求綁定入口。
//
// @ai:generated by=claude-opus-4-8 date=2026-06-11
// @ai:purpose 收斂「解析 + 驗證 + 對齊 Schema 宣告 + 錯誤格式」為單一慣例，
//
//	補上 Contract Testing 結構上抓不到的「handler 綁錯 struct 靜默失敗」缺口
package context

import (
	"encoding/json"
	stderrors "errors"
	"fmt"
	"io"
	"net/http"
	"reflect"
	"strings"
	"sync/atomic"

	"github.com/go-playground/validator/v10"
	hypvalidate "github.com/maoxiaoyue/hypgo/pkg/validate"
)

// BindInputReporter 在 handler 綁定的型別與 Schema 宣告不符時被呼叫。
// 以 hook 形式提供，讓 server/app 可接到 logger，而 pkg/context 不需依賴 pkg/logger（避免循環依賴）。
type BindInputReporter func(routeKey, declared, bound string)

// bindInputReporter 以 atomic 保存：server.Start 寫入時，其他 server（或重啟中的同一行程）
// 的請求可能正在讀取——先前的裸變數是 data race
var bindInputReporter atomic.Pointer[BindInputReporter]

// SetBindInputReporter 設定型別不符的回報函式。
//
// @ai:generated by=claude-opus-4-8 date=2026-06-11
// @ai:purpose 讓上層（server）注入 logger 回報，維持 context 對 logger 零依賴
// @ai:input 回報函式，參數為 routeKey、宣告型別名、實際綁定型別名
// @ai:output none
// @ai:sideeffect 設定套件層級變數（並行安全；後設定者覆蓋先前的值）
func SetBindInputReporter(fn BindInputReporter) {
	if fn == nil {
		bindInputReporter.Store(nil)
		return
	}
	bindInputReporter.Store(&fn)
}

// SetSchemaInput 記錄當前路由宣告的 Input 型別，供 BindInput 對齊比對。
// 由 router 在註冊 schema 路由時，以一個前置 handler 在每次請求設定。
//
// @ai:generated by=claude-opus-4-8 date=2026-06-11
// @ai:purpose 將 Schema 宣告的 Input 型別帶入請求上下文，使 BindInput 能在執行期偵測綁錯型別
// @ai:input schema RouteKey 字串、該路由宣告的 Input 零值實例
// @ai:output none
// @ai:sideeffect 設定 Context 內部欄位
func (c *Context) SetSchemaInput(routeKey string, input interface{}) {
	c.schemaRouteKey = routeKey
	c.schemaInput = input
}

// BindInputCalled 回報本請求是否呼叫過 BindInput。
//
// @ai:generated by=claude-opus-4-8 date=2026-06-11
// @ai:purpose 供啟動 lint 的 runtime 偵測（機制 B）確認 schema 路由的 handler 是否使用了 BindInput
// @ai:input none
// @ai:output bool（true 表示本請求已呼叫 BindInput）
// @ai:sideeffect none
func (c *Context) BindInputCalled() bool {
	return c.bindInputCalled
}

// BindInput 解析請求 body 到 obj、執行 validate tag 驗證，並對齊 Schema 宣告型別。
//
// 失敗時自動以 Error Catalog 形狀的 JSON 中斷請求並回傳 false：
//   - 解析失敗 → 400 {"code":"E0002","message":"Bad request"}
//   - 有 body 但 Content-Type 認不得 → 415 {"code":"E0005","message":"Unsupported media type"}
//   - body 超過上限 → 413 {"code":"E0006","message":"Request body too large"}
//   - 驗證失敗 → 422 {"code":"E1001","message":"Validation failed","details":{欄位路徑:訊息}}
//
// obj 可以是 struct、slice 或 map 的指標；slice / map 的元素逐一驗證。
//
// 成功回傳 true，呼叫端可直接使用 obj。典型用法：
//
//	var req CreateUserReq
//	if !c.BindInput(&req) { return }
//
// @ai:generated by=claude-opus-4-8 date=2026-06-11
// @ai:purpose 提供 Schema-first 路由的標準綁定入口，收斂 AI/人各自手寫 unmarshal+驗證+錯誤處理的歧異
// @ai:input 指向目標 struct 的指標（obj）
// @ai:output bool（true=成功並已填入 obj；false=已中斷請求並寫出錯誤回應）
// @ai:sideeffect 讀取 Request body；失敗時寫出 HTTP 4xx JSON 並中止 middleware 鏈；型別不符時觸發 reporter
// @ai:security 驗證使用全框架共用 validator，與 pkg/json 規則一致；錯誤訊息不洩漏內部結構
func (c *Context) BindInput(obj interface{}) bool {
	c.bindInputCalled = true

	// 1. 對齊 Schema 宣告型別：偵測 handler 綁錯 struct 的靜默失敗
	//    （Go 的 json.Unmarshal 綁錯型別不會報錯，這是整條工具鏈唯一能攔截之處）
	if report := bindInputReporter.Load(); c.schemaInput != nil && report != nil {
		declared := derefType(reflect.TypeOf(c.schemaInput))
		bound := derefType(reflect.TypeOf(obj))
		if declared != nil && bound != nil && declared != bound {
			(*report)(c.schemaRouteKey, declared.String(), bound.String())
		}
	}

	// 2. 依 Content-Type 解析（JSON / form / query 等）
	if err := c.ShouldBind(obj); err != nil {
		var tooBig *http.MaxBytesError
		switch {
		case stderrors.Is(err, ErrUnsupportedMediaType):
			c.abortBindError(http.StatusUnsupportedMediaType, "E0005", "Unsupported media type",
				map[string]interface{}{"reason": err.Error()})
		case stderrors.As(err, &tooBig):
			c.abortBindError(http.StatusRequestEntityTooLarge, "E0006", "Request body too large",
				map[string]interface{}{"limit": tooBig.Limit})
		default:
			c.abortBindError(http.StatusBadRequest, "E0002", "Bad request",
				map[string]interface{}{"reason": bindReason(err)})
		}
		return false
	}

	// 3. 執行 validate tag 驗證（共用 registry，與 pkg/json 同步生效）
	if err := validateBound(obj); err != nil {
		c.abortBindError(http.StatusUnprocessableEntity, "E1001", "Validation failed",
			validationDetails(err))
		return false
	}

	return true
}

// validateBound 驗證綁定結果：struct 走 validate tag，slice / array / map 逐一驗證元素。
// 先前一律呼叫 validator.Struct：綁到 []Item 或 map 時它回 InvalidValidationError，
// 合法的 JSON 陣列也被當成驗證失敗回 422
func validateBound(obj interface{}) error {
	v := reflect.ValueOf(obj)
	for v.Kind() == reflect.Ptr && !v.IsNil() {
		v = v.Elem()
	}
	switch v.Kind() {
	case reflect.Struct:
		return hypvalidate.Struct(obj)
	case reflect.Slice, reflect.Array, reflect.Map:
		return hypvalidate.Var(v.Interface(), "dive")
	}
	return nil
}

// bindReason 把綁定錯誤轉成給客戶端看的說明，不帶 Go 的型別名。
// 先前直接輸出 err.Error()：json: cannot unmarshal string into Go struct field Req.age of type int，
// 空 body 則只有 "EOF"
func bindReason(err error) string {
	var typeErr *json.UnmarshalTypeError
	var syntaxErr *json.SyntaxError
	switch {
	case stderrors.Is(err, io.EOF):
		return "request body is empty"
	case stderrors.Is(err, io.ErrUnexpectedEOF):
		return "request body is truncated"
	case stderrors.As(err, &typeErr):
		if typeErr.Field == "" {
			return fmt.Sprintf("expected %s, got %s", jsonKind(typeErr.Type), typeErr.Value)
		}
		return fmt.Sprintf("field %q must be %s, got %s", typeErr.Field, jsonKind(typeErr.Type), typeErr.Value)
	case stderrors.As(err, &syntaxErr):
		return fmt.Sprintf("invalid JSON at offset %d", syntaxErr.Offset)
	}
	return err.Error()
}

// jsonKind Go 型別對應的 JSON 型別名稱
func jsonKind(t reflect.Type) string {
	if t = derefType(t); t == nil {
		return "a valid value"
	}
	switch t.Kind() {
	case reflect.String:
		return "a string"
	case reflect.Bool:
		return "a boolean"
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64,
		reflect.Float32, reflect.Float64:
		return "a number"
	case reflect.Slice, reflect.Array:
		return "an array"
	case reflect.Struct, reflect.Map:
		return "an object"
	}
	return "a valid value"
}

// derefType 解開指標層，回傳底層型別
func derefType(t reflect.Type) reflect.Type {
	for t != nil && t.Kind() == reflect.Ptr {
		t = t.Elem()
	}
	return t
}

// abortBindError 以 Error Catalog 形狀輸出錯誤 JSON。
// 直接組裝 map 而不 import pkg/errors，避免 context ← errors 的循環依賴。
func (c *Context) abortBindError(status int, code, message string, details map[string]interface{}) {
	body := map[string]interface{}{
		"code":    code,
		"message": message,
	}
	if len(details) > 0 {
		body["details"] = details
	}
	c.AbortWithStatusJSON(status, body)
}

// validationDetails 將 validator 錯誤轉為 欄位路徑 → 可讀訊息 的細節 map。
// key 是完整路徑（billing.city、items[1].city）：先前只取最後一段，
// billing.city 與 shipping.city 同時缺少時互相覆蓋，只剩一筆 city
func validationDetails(err error) map[string]interface{} {
	details := map[string]interface{}{}
	var verrs validator.ValidationErrors
	if stderrors.As(err, &verrs) {
		for _, fe := range verrs {
			details[fieldPath(fe)] = validationMessage(fe)
		}
	} else {
		details["error"] = err.Error()
	}
	return details
}

// fieldPath 回傳欄位在請求裡的路徑：去掉 validator namespace 開頭的型別名
// （Order.billing.city → billing.city；slice 的 [1].name 原樣保留）
func fieldPath(fe validator.FieldError) string {
	ns := fe.Namespace()
	if i := strings.IndexAny(ns, ".["); i >= 0 {
		if ns[i] == '.' {
			return ns[i+1:]
		}
		return ns[i:]
	}
	if f := fe.Field(); f != "" {
		return f
	}
	return ns
}

// validationMessage 依驗證規則產生可讀訊息（對齊 pkg/json 的訊息風格）
func validationMessage(fe validator.FieldError) string {
	field := fe.Field()
	switch fe.Tag() {
	case "required":
		return field + " is required"
	case "email":
		return field + " must be a valid email address"
	case "min":
		return field + " must be at least " + fe.Param()
	case "max":
		return field + " must not exceed " + fe.Param()
	case "oneof":
		return field + " must be one of [" + fe.Param() + "]"
	case "gte":
		return field + " must be >= " + fe.Param()
	case "lte":
		return field + " must be <= " + fe.Param()
	case "gt":
		return field + " must be > " + fe.Param()
	case "lt":
		return field + " must be < " + fe.Param()
	default:
		return field + " failed " + fe.Tag() + " validation"
	}
}
